<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Liner Jet</title>
  <style>
    :root {
      --bg:        oklch(14% 0.01 260);
      --surface:   oklch(19% 0.015 260);
      --border:    oklch(28% 0.02 260);
      --muted:     oklch(55% 0.02 260);
      --body:      oklch(88% 0.01 260);
      --accent:    oklch(72% 0.19 210);
      --accent-lo: oklch(62% 0.19 210 / 0.18);
      --trail:     oklch(72% 0.19 210 / 0.0);
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background: var(--bg);
      color: var(--body);
      font-family: system-ui, sans-serif;
      min-height: 100vh;
      display: grid;
      place-items: center;
      overflow: hidden;
    }

    .scene {
      position: relative;
      width: min(640px, 92vw);
      height: 220px;
    }

    /* ── trail lines ── */
    .trail {
      position: absolute;
      top: 50%;
      left: 0;
      width: 100%;
      height: 1px;
      transform: translateY(-50%);
      pointer-events: none;
    }

    .trail::before,
    .trail::after {
      content: "";
      position: absolute;
      inset-block: 0;
      left: 0;
      width: 100%;
      background: linear-gradient(
        90deg,
        var(--trail),
        var(--accent-lo) 40%,
        var(--accent) 100%
      );
      animation: trail-sweep 2.4s cubic-bezier(0.4, 0, 0.2, 1) infinite;
    }

    .trail::before { top: -7px; }
    .trail::after  { top:  7px; }

    @keyframes trail-sweep {
      0%   { clip-path: inset(0 100% 0 0); opacity: 0; }
      10%  { opacity: 1; }
      60%  { clip-path: inset(0 0% 0 0); }
      100% { clip-path: inset(0 0% 0 0); opacity: 0; }
    }

    /* ── jet body ── */
    .jet {
      position: absolute;
      top: 50%;
      left: -80px;
      transform: translateY(-50%);
      width: 88px;
      height: 28px;
      animation: fly 2.4s cubic-bezier(0.4, 0, 0.2, 1) infinite;
      will-change: transform;
    }

    @keyframes fly {
      0%   { left: -88px;  opacity: 0; }
      8%   { opacity: 1; }
      85%  { opacity: 1; }
      100% { left: calc(100% + 88px); opacity: 0; }
    }

    .jet svg {
      width: 100%;
      height: 100%;
      overflow: visible;
    }

    /* ── label ── */
    .label {
      position: absolute;
      bottom: 24px;
      left: 50%;
      transform: translateX(-50%);
      font-size: 0.7rem;
      letter-spacing: 0.22em;
      text-transform: uppercase;
      color: var(--muted);
      white-space: nowrap;
      animation: fade-in 0.6s 0.2s both;
    }

    @keyframes fade-in {
      from { opacity: 0; transform: translateX(-50%) translateY(6px); }
      to   { opacity: 1; transform: translateX(-50%) translateY(0); }
    }

    /* ── horizon lines ── */
    .horizon {
      position: absolute;
      top: 50%;
      left: 0;
      width: 100%;
      display: flex;
      flex-direction: column;
      gap: 14px;
      transform: translateY(-50%);
      pointer-events: none;
    }

    .horizon span {
      display: block;
      height: 1px;
      background: var(--border);
      width: 100%;
    }
  </style>
</head>
